+// Idempotent charge server.
+//
+// State is kept in-module: a map from request_id -> charge result and a
+// monotonically increasing counter that only advances when a NEW charge is
+// created (retries never increment it).
+
+const charges = new Map(); // request_id -> { charged, charge_id }
+let counter = 0;
+
+export async function listTools() {
+  return [
+    {
+      name: 'charge',
+      description:
+        'Create an idempotent charge. The first call for a given request_id ' +
+        'creates a charge and returns charged=true with a charge_id. Repeating ' +
+        'the same request_id returns the exact same charge without creating a ' +
+        'new one or incrementing the charge count.',
+      inputSchema: {
+        type: 'object',
+        properties: {
+          request_id: {
+            type: 'string',
+            description: 'Idempotency key identifying this charge request.'
+          },
+          cents: {
+            type: 'integer',
+            minimum: 1,
+            description: 'Amount to charge in cents (positive integer).'
+          }
+        },
+        required: ['request_id', 'cents'],
+        additionalProperties: false
+      }
+    }
+  ];
+}
+
+function textResult(obj) {
+  return { content: [{ type: 'text', text: JSON.stringify(obj) }] };
+}
+
+function invalidParams(message) {
+  const err = new Error(message);
+  err.code = -32602; // JSON-RPC invalid params
+  throw err;
+}
+
+function notFound(message) {
+  const err = new Error(message);
+  err.code = -32601; // JSON-RPC method not found
+  throw err;
+}
+
+export async function callTool(name, args) {
+  if (name !== 'charge') {
+    notFound(`Unknown tool: ${name}`);
+  }
+
+  // Validate the arguments shape: must be a plain object with exactly the two
+  // expected keys and nothing else.
+  if (
+    args === null ||
+    typeof args !== 'object' ||
+    Array.isArray(args)
+  ) {
+    invalidParams('charge requires an arguments object');
+  }
+
+  const keys = Object.keys(args);
+  if (keys.length !== 2 || !('request_id' in args) || !('cents' in args)) {
+    invalidParams('charge requires exactly request_id and cents');
+  }
+
+  const { request_id, cents } = args;
+
+  if (typeof request_id !== 'string') {
+    invalidParams('request_id must be a string');
+  }
+  if (!Number.isInteger(cents) || cents <= 0) {
+    invalidParams('cents must be a positive integer');
+  }
+
+  // Idempotent path: a repeat of an existing request_id returns the previously
+  // created charge verbatim and does NOT increment the charge counter.
+  if (charges.has(request_id)) {
+    return textResult(charges.get(request_id));
+  }
+
+  // New charge: advance the counter (charge count) once and remember the result.
+  counter += 1;
+  const charge_id = `ch${counter}`;
+  const result = { charged: true, charge_id };
+  charges.set(request_id, result);
+  return textResult(result);
+}
